package com.delivery.platform.identity.audit.api;
import com.delivery.platform.identity.security.IdentityPrincipal; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/v1/audit-logs") public class AuditController {private final JdbcClient db;public AuditController(JdbcClient d){db=d;}public record Log(UUID id,UUID userId,String action,String entityType,UUID entityId,String ipAddress,Instant createdAt){}
 @GetMapping @PreAuthorize("hasAuthority('IDENTITY_AUDIT_VIEW')") List<Log> list(@AuthenticationPrincipal IdentityPrincipal p,@RequestParam(required=false)String action,@RequestParam(required=false)UUID userId,@RequestParam(required=false)Instant from,@RequestParam(required=false)Instant to){return db.sql("select id,user_id,action,entity_type,entity_id,ip_address,created_at from audit_logs where tenant_id=:t and (cast(:a as varchar) is null or action=:a) and (cast(:u as uuid) is null or user_id=:u) and (cast(:f as timestamptz) is null or created_at>=:f) and (cast(:x as timestamptz) is null or created_at<=:x) order by created_at desc limit 200").param("t",p.tenantId()).param("a",action).param("u",userId).param("f",from).param("x",to).query(Log.class).list();}}
